def load_parameter_definitions(path: Optional[str], initial_params: Dict[str, Any]) -> Dict[str, ParameterDefinition]:
    definitions: Dict[str, ParameterDefinition] = {}
    loaded: Dict[str, Any] = {}
    if path and os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                loaded = json.load(f)
        except Exception:
            loaded = {}
    keys = set(initial_params.keys()) | set(loaded.keys())
    for k in keys:
        spec = loaded.get(k, {})
        definitions[k] = ParameterDefinition(
            key=k,
            dtype=spec.get("dtype", "float"),
            default=spec.get("default", initial_params.get(k, 0.0)),
            low=spec.get("bounds", {}).get("low"),
            high=spec.get("bounds", {}).get("high"),
            owner_module=spec.get("owner_module", "global"),
            frozen=spec.get("frozen", False),
            description=spec.get("description", "")
        )
    for fk in ["random_seed", "network_type_code", "adoption_rule_code"]:
        if fk in definitions:
            definitions[fk].frozen = True
    if "capture_micro" not in definitions:
        definitions["capture_micro"] = ParameterDefinition(key="capture_micro", dtype="bool", default=False, owner_module="InfluencePropagation")
    if "save_micro_io" not in definitions:
        definitions["save_micro_io"] = ParameterDefinition(key="save_micro_io", dtype="bool", default=False, owner_module="global")
    if "micro_sample_frac" not in definitions:
        definitions["micro_sample_frac"] = ParameterDefinition(key="micro_sample_frac", dtype="float", default=0.1, low=0.0, high=1.0, owner_module="InfluencePropagation")
    if "save_heavy_io" not in definitions:
        definitions["save_heavy_io"] = ParameterDefinition(key="save_heavy_io", dtype="bool", default=False, owner_module="global")
    if "io_agent_sample_n" not in definitions:
        definitions["io_agent_sample_n"] = ParameterDefinition(key="io_agent_sample_n", dtype="int", default=100, low=0, high=10000, owner_module="global")
    return definitions

